class Solution:
    def findRadius(self, houses: List[int], heaters: List[int]) -> int:
        houses.sort()
        heaters.sort()
        ans = 0
        import bisect
        for h in houses:
            i = bisect.bisect_left(heaters, h)
            d = float('inf')
            if i < len(heaters):
                d = min(d, heaters[i] - h)
            if i > 0:
                d = min(d, h - heaters[i - 1])
            ans = max(ans, d)
        return ans

