import java.util.*;
class Solution {
    public int findRadius(int[] houses, int[] heaters) {
        Arrays.sort(houses);
        Arrays.sort(heaters);
        long ans = 0;
        for (int h : houses) {
            int i = Arrays.binarySearch(heaters, h);
            if (i < 0) i = -(i + 1);
            long d = Long.MAX_VALUE;
            if (i < heaters.length) d = Math.min(d, (long) heaters[i] - h);
            if (i > 0) d = Math.min(d, (long) h - heaters[i - 1]);
            ans = Math.max(ans, d);
        }
        return (int) ans;
    }
}

