var findRadius = function(houses, heaters) {
    houses.sort((a, b) => a - b);
    heaters.sort((a, b) => a - b);
    let ans = 0;
    for (const h of houses) {
        let lo = 0, hi = heaters.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (heaters[mid] < h) lo = mid + 1; else hi = mid;
        }
        let d = Infinity;
        if (lo < heaters.length) d = Math.min(d, heaters[lo] - h);
        if (lo > 0) d = Math.min(d, h - heaters[lo - 1]);
        ans = Math.max(ans, d);
    }
    return ans;
};

