        houses.sort()
        heaters.sort()
        j, ans = 0, 0
        for h in houses:
            while j + 1 < len(heaters) and abs(heaters[j + 1] - h) <= abs(heaters[j] - h):
                j += 1
            ans = max(ans, abs(heaters[j] - h))
